using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        SeedStudents();
        _controller = new StudentsController(_context);
    }

    private void SeedStudents()
    {
        _context.Students.AddRange(
            new Student { ID = 1, LastName = "Alexander", FirstMidName = "Carson", EnrollmentDate = new DateTime(2020, 9, 1) },
            new Student { ID = 2, LastName = "Alonso", FirstMidName = "Meredith", EnrollmentDate = new DateTime(2021, 9, 1) },
            new Student { ID = 3, LastName = "Barzdukas", FirstMidName = "Gytis", EnrollmentDate = new DateTime(2019, 9, 1) }
        );
        _context.SaveChanges();
    }

    [Fact]
    public void Index_ReturnsViewResult_WithPaginatedList()
    {
        var result = _controller.Index(null, null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(3, model.Count);
    }

    [Fact]
    public void Index_SortsByNameDescending()
    {
        var result = _controller.Index("name_desc", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Barzdukas", model[0].LastName);
    }

    [Fact]
    public void Index_SortsByDateAscending()
    {
        var result = _controller.Index("Date", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Barzdukas", model[0].LastName);
    }

    [Fact]
    public void Index_SortsByDateDescending()
    {
        var result = _controller.Index("date_desc", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Alonso", model[0].LastName);
    }

    [Fact]
    public void Index_DefaultSortsByNameAscending()
    {
        var result = _controller.Index(null, null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_FiltersStudentsBySearchString()
    {
        var result = _controller.Index(null, null, "Alonso", null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Alonso", model[0].LastName);
    }

    [Fact]
    public void Index_SearchByFirstName()
    {
        var result = _controller.Index(null, null, "Carson", null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_ResetsPageToOneWhenSearchStringProvided()
    {
        var result = _controller.Index(null, null, "Alexander", 3);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_UsesCurrentFilterWhenSearchStringIsNull()
    {
        var result = _controller.Index(null, "Alonso", null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Single(model);
    }

    [Fact]
    public void Details_ReturnsNotFound_WhenIdIsNull()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ReturnsViewResult_WithStudent()
    {
        // Need enrollments for Include
        var result = _controller.Details(1);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal("Alexander", model.LastName);
    }

    [Fact]
    public void Create_GET_ReturnsViewResult_WithStudentModel()
    {
        var result = _controller.Create();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    [Fact]
    public void Create_POST_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            LastName = "TestLast",
            FirstMidName = "TestFirst",
            EnrollmentDate = new DateTime(2023, 1, 15)
        };

        var result = _controller.Create(student);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Create_POST_ValidStudent_AddsToDatabase()
    {
        var student = new Student
        {
            LastName = "NewStudent",
            FirstMidName = "First",
            EnrollmentDate = new DateTime(2023, 6, 1)
        };

        _controller.Create(student);

        Assert.Equal(4, _context.Students.Count());
        Assert.Contains(_context.Students, s => s.LastName == "NewStudent");
    }

    [Fact]
    public void Create_POST_InvalidEnrollmentDate_ReturnsView()
    {
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "Student",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal(student, viewResult.Model);
    }

    [Fact]
    public void Create_POST_EnrollmentDateOutOfRange_ReturnsView()
    {
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "Student",
            EnrollmentDate = new DateTime(1000, 1, 1)
        };

        var result = _controller.Create(student);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal(student, viewResult.Model);
    }

    [Fact]
    public void Edit_GET_ReturnsNotFound_WhenIdIsNull()
    {
        var result = _controller.Edit((int?)null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_GET_ReturnsNotFound_WhenStudentNotFound()
    {
        var result = _controller.Edit(999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_GET_ReturnsViewResult_WithStudent()
    {
        var result = _controller.Edit(1);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal("Alexander", model.LastName);
    }

    [Fact]
    public void Edit_POST_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            ID = 1,
            LastName = "UpdatedName",
            FirstMidName = "Carson",
            EnrollmentDate = new DateTime(2020, 9, 1)
        };
        // Detach existing tracked entity
        var existing = _context.Students.Find(1);
        _context.Entry(existing).State = EntityState.Detached;

        var result = _controller.Edit(student);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Edit_POST_InvalidEnrollmentDate_ReturnsView()
    {
        var student = new Student
