using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;

    public CoursesControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _mockEnv = new Mock<IWebHostEnvironment>();
        _mockEnv.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        _mockEnv.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _mockLogger = new Mock<ILogger<CoursesController>>();
        SeedData();
        _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
    }

    private void SeedData()
    {
        var dept = new Department { DepartmentID = 1, Name = "Engineering", Budget = 100000, StartDate = new DateTime(2020, 1, 1) };
        _context.Departments.Add(dept);

        _context.Courses.AddRange(
            new Course { CourseID = 1001, Title = "Chemistry", Credits = 3, DepartmentID = 1 },
            new Course { CourseID = 1002, Title = "Physics", Credits = 4, DepartmentID = 1 },
            new Course { CourseID = 1003, Title = "Math", Credits = 3, DepartmentID = 1 }
        );
        _context.SaveChanges();
    }

    [Fact]
    public void Index_ReturnsViewResult_WithListOfCourses()
    {
        var result = _controller.Index();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Course>>(viewResult.Model);
        Assert.Equal(3, model.Count);
    }

    [Fact]
    public void Details_ReturnsBadRequest_WhenIdIsNull()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ReturnsViewResult_WithCourse()
    {
        var result = _controller.Details(1001);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Course>(viewResult.Model);
        Assert.Equal("Chemistry", model.Title);
    }

    [Fact]
    public void Create_GET_ReturnsViewResult()
    {
        var result = _controller.Create();

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.IsType<Course>(viewResult.Model);
    }

    [Fact]
    public void Create_POST_ValidCourse_RedirectsToIndex()
    {
        var course = new Course
        {
            CourseID = 2001,
            Title = "New Course",
            Credits = 3,
            DepartmentID = 1
        };

        var result = _controller.Create(course, null);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Create_POST_ValidCourse_AddsToDatabase()
    {
        var course = new Course
        {
            CourseID = 2002,
            Title = "Another Course",
            Credits = 4,
            DepartmentID = 1
        };

        _controller.Create(course, null);

        Assert.Equal(4, _context.Courses.Count());
    }

    [Fact]
    public void Create_POST_InvalidModel_ReturnsView()
    {
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 3001, DepartmentID = 1 };

        var result = _controller.Create(course, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal(course, viewResult.Model);
    }

    [Fact]
    public void Create_POST_WithInvalidFileExtension_ReturnsView()
    {
        var course = new Course { CourseID = 3001, Title = "Test", Credits = 3, DepartmentID = 1 };
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns("test.exe");
        mockFile.Setup(f => f.Length).Returns(1024);

        var result = _controller.Create(course, mockFile.Object);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal(course, viewResult.Model);
    }

    [Fact]
    public void Create_POST_WithOversizedFile_ReturnsView()
    {
        var course = new Course { CourseID = 3001, Title = "Test", Credits = 3, DepartmentID = 1 };
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns("test.jpg");
        mockFile.Setup(f => f.Length).Returns(10 * 1024 * 1024); // 10MB

        var result = _controller.Create(course, mockFile.Object);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal(course, viewResult.Model);
    }

    [Fact]
    public void Edit_GET_ReturnsBadRequest_WhenIdIsNull()
    {
        var result = _controller.Edit((int?)null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_GET_ReturnsNotFound_WhenCourseNotFound()
    {
        var result = _controller.Edit(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_GET_ReturnsViewResult_WithCourse()
    {
        var result = _controller.Edit(1001);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Course>(viewResult.Model);
        Assert.Equal("Chemistry", model.Title);
    }

    [Fact]
    public void Edit_POST_ValidCourse_RedirectsToIndex()
    {
        var course = new Course
        {
            CourseID = 1001,
            Title = "Updated Chemistry",
            Credits = 4,
            DepartmentID = 1
        };
        var existing = _context.Courses.Find(1001);
        _context.Entry(existing).State = EntityState.Detached;

        var result = _controller.Edit(course, null);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Edit_POST_InvalidModel_ReturnsView()
    {
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 1001, DepartmentID = 1 };

        var result = _controller.Edit(course, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal(course, viewResult.Model);
    }

    [Fact]
    public void Edit_POST_WithInvalidFileExtension_ReturnsView()
    {
        var course = new Course { CourseID = 1001, Title = "Chemistry", Credits = 3, DepartmentID = 1 };
        var existing = _context.Courses.Find(1001);
        _context.Entry(existing).State = EntityState.Detached;

        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns("test.exe");
        mockFile.Setup(f => f.Length).Returns(1024);

        var result = _controller.Edit(course, mockFile.Object);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal(course, viewResult.Model);
    }

    [Fact]
    public void Delete_GET_ReturnsBadRequest_WhenIdIsNull()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_GET_ReturnsViewResult_WithCourse()
    {
        var result = _controller.Delete(1001);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Course>(viewResult.Model);
        Assert.Equal("Chemistry", model.Title);
    }

    [Fact]
    public void DeleteConfirmed_RemovesCourseAndRedirects()
    {
        var result = _controller.DeleteConfirmed(1001);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
        Assert.Equal(2, _context.Courses.Count());
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }
}

