using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class DepartmentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly DepartmentsController _controller;

    public DepartmentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        SeedData();
        _controller = new DepartmentsController(_context);
    }

    private void SeedData()
    {
        var instructor = new Instructor { ID = 1, LastName = "Smith", FirstMidName = "John", HireDate = new DateTime(2010, 1, 1) };
        _context.Instructors.Add(instructor);

        _context.Departments.AddRange(
            new Department { DepartmentID = 1, Name = "Engineering", Budget = 100000, StartDate = new DateTime(2020, 1, 1), InstructorID = 1 },
            new Department { DepartmentID = 2, Name = "Science", Budget = 80000, StartDate = new DateTime(2019, 1, 1) },
            new Department { DepartmentID = 3, Name = "Arts", Budget = 50000, StartDate = new DateTime(2018, 1, 1) }
        );
        _context.SaveChanges();
    }

    [Fact]
    public void Index_ReturnsViewResult_WithListOfDepartments()
    {
        var result = _controller.Index();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
        Assert.Equal(3, model.Count);
    }

    [Fact]
    public void Details_ReturnsBadRequest_WhenIdIsNull()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ReturnsNotFound_WhenDepartmentNotFound()
    {
        var result = _controller.Details(999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_ReturnsViewResult_WithDepartment()
    {
        var result = _controller.Details(1);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Department>(viewResult.Model);
        Assert.Equal("Engineering", model.Name);
    }

    [Fact]
    public void Create_GET_ReturnsViewResult()
    {
        var result = _controller.Create();

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void Create_POST_ValidDepartment_RedirectsToIndex()
    {
        var department = new Department
        {
            Name = "New Dept",
            Budget = 60000,
            StartDate = new DateTime(2023, 1, 1)
        };

        var result = _controller.Create(department);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Create_POST_ValidDepartment_AddsToDatabase()
    {
        var department = new Department
        {
            Name = "Mathematics",
            Budget = 75000,
            StartDate = new DateTime(2023, 6, 1)
        };

        _controller.Create(department);

        Assert.Equal(4, _context.Departments.Count());
    }

    [Fact]
    public void Create_POST_InvalidModel_ReturnsView()
    {
        _controller.ModelState.AddModelError("Name", "Required");
        var department = new Department();

        var result = _controller.Create(department);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal(department, viewResult.Model);
    }

    [Fact]
    public void Edit_GET_ReturnsBadRequest_WhenIdIsNull()
    {
        var result = _controller.Edit((int?)null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_GET_ReturnsNotFound_WhenDepartmentNotFound()
    {
        var result = _controller.Edit(999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_GET_ReturnsViewResult_WithDepartment()
    {
        var result = _controller.Edit(1);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Department>(viewResult.Model);
        Assert.Equal("Engineering", model.Name);
    }

    [Fact]
    public void Edit_POST_ValidDepartment_RedirectsToIndex()
    {
        var department = new Department
        {
            DepartmentID = 2,
            Name = "Updated Science",
            Budget = 90000,
            StartDate = new DateTime(2019, 1, 1)
        };
        var existing = _context.Departments.Find(2);
        _context.Entry(existing).State = EntityState.Detached;

        var result = _controller.Edit(department);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Edit_POST_InvalidModel_ReturnsView()
    {
        _controller.ModelState.AddModelError("Name", "Required");
        var department = new Department { DepartmentID = 1 };

        var result = _controller.Edit(department);

        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal(department, viewResult.Model);
    }

    [Fact]
    public void Delete_GET_ReturnsBadRequest_WhenIdIsNull()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_GET_ReturnsNotFound_WhenDepartmentNotFound()
    {
        var result = _controller.Delete(999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_GET_ReturnsViewResult_WithDepartment()
    {
        var result = _controller.Delete(2);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Department>(viewResult.Model);
        Assert.Equal("Science", model.Name);
    }

    [Fact]
    public void DeleteConfirmed_RemovesDepartmentAndRedirects()
    {
        var result = _controller.DeleteConfirmed(3);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
        Assert.Equal(2, _context.Departments.Count());
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }
}

