using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        SeedData();
        _controller = new InstructorsController(_context);
    }

    private void SeedData()
    {
        var dept = new Department { DepartmentID = 1, Name = "Engineering", Budget = 100000, StartDate = new DateTime(2020, 1, 1) };
        _context.Departments.Add(dept);

        var course1 = new Course { CourseID = 101, Title = "Intro CS", Credits = 3, DepartmentID = 1 };
        var course2 = new Course { CourseID = 102, Title = "Data Structures", Credits = 4, DepartmentID = 1 };
        _context.Courses.AddRange(course1, course2);

        var instructor1 = new Instructor
        {
            ID = 1,
            LastName = "Kapoor",
            FirstMidName = "Candace",
            HireDate = new DateTime(2015, 3, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        var instructor2 = new Instructor
        {
            ID = 2,
            LastName = "Harui",
            FirstMidName = "Roger",
            HireDate = new DateTime(2018, 7, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.AddRange(instructor1, instructor2);
        _context.SaveChanges();

        _context.CourseAssignments.Add(new CourseAssignment { InstructorID = 1, CourseID = 101 });
        _context.CourseAssignments.Add(new CourseAssignment { InstructorID = 1, CourseID = 102 });
        _context.SaveChanges();
    }

    [Fact]
    public void Index_ReturnsViewResult_WithInstructorIndexData()
    {
        var result = _controller.Index(null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<Models.SchoolViewModels.InstructorIndexData>(viewResult.Model);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_WithInstructorId_PopulatesCourses()
    {
        var result = _controller.Index(1, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<Models.SchoolViewModels.InstructorIndexData>(viewResult.Model);
        Assert.NotNull(model.Courses);
        Assert.Equal(2, model.Courses.Count());
    }

    [Fact]
    public void Index_WithCourseId_PopulatesEnrollments()
    {
        // Add enrollment for the course
        var student = new Student { ID = 10, LastName = "Test", FirstMidName = "Stu", EnrollmentDate = DateTime.Now };
        _context.Students.Add(student);
        _context.Enrollments.Add(new Enrollment { CourseID = 101, StudentID = 10, Grade = Grade.A });
        _context.SaveChanges();

        var result = _controller.Index(1, 101);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<Models.SchoolViewModels.InstructorIndexData>(viewResult.Model);
        Assert.NotNull(model.Enrollments);
        Assert.Single(model.Enrollments);
    }

    [Fact]
    public void Details_ReturnsBadRequest_WhenIdIsNull()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ReturnsNotFound_WhenInstructorNotFound()
    {
        var result = _controller.Details(999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_ReturnsViewResult_WithInstructor()
    {
        var result = _controller.Details(1);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal("Kapoor", model.LastName);
    }

    [Fact]
    public void Create_GET_ReturnsViewResult_WithInstructor()
    {
        var result = _controller.Create();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.NotNull(model.CourseAssignments);
    }

    [Fact]
    public void Create_POST_ValidInstructor_RedirectsToIndex()
    {
        var instructor = new Instructor
        {
            LastName = "NewInstructor",
            FirstMidName = "Test",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Create_POST_WithSelectedCourses_AddsCourseAssignments()
    {
        var instructor = new Instructor
        {
            LastName = "WithCourses",
            FirstMidName = "Instructor",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        _controller.Create(instructor, new[] { "101", "102" });

        var saved = _context.Instructors.Include(i => i.CourseAssignments)
            .Single(i => i.LastName == "WithCourses");
        Assert.Equal(2, saved.CourseAssignments.Count);
    }

    [Fact]
    public void Create_POST_InvalidModel_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor { CourseAssignments = new List<CourseAssignment>() };

        var result = _controller.Create(instructor, null);

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void Edit_GET_ReturnsBadRequest_WhenIdIsNull()
    {
        var result = _controller.Edit((int?)null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_GET_ReturnsViewResult_WithInstructor()
    {
        var result = _controller.Edit(1);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal("Kapoor", model.LastName);
    }

    [Fact]
    public void Delete_GET_ReturnsBadRequest_WhenIdIsNull()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_GET_ReturnsNotFound_WhenInstructorNotFound()
    {
        var result = _controller.Delete(999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_GET_ReturnsViewResult_WithInstructor()
    {
        var result = _controller.Delete(2);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal("Harui", model.LastName);
    }

    [Fact]
    public void DeleteConfirmed_RemovesInstructorAndRedirects()
    {
        var result = _controller.DeleteConfirmed(2);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
        Assert.Single(_context.Instructors);
    }

    [Fact]
    public void DeleteConfirmed_NullsDepartmentAdministrator()
    {
        // Assign instructor 2 as dept administrator
        var dept = _context.Departments.Find(1);
        dept.InstructorID = 2;
        _context.SaveChanges();

        _controller.DeleteConfirmed(2);

        var updatedDept = _context.Departments.Find(1);
        Assert.Null(updatedDept.InstructorID);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }
}

