using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data;

public class SchoolContextTests : IDisposable
{
    private readonly SchoolContext _context;

    public SchoolContextTests()
    {
        _context = TestDbContextFactory.Create();
    }

    [Fact]
    public void CanAddAndRetrieveStudent()
    {
        var student = new Student
        {
            LastName = "TestStudent",
            FirstMidName = "First",
            EnrollmentDate = new DateTime(2023, 1, 1)
        };

        _context.Students.Add(student);
        _context.SaveChanges();

        var retrieved = _context.Students.Single(s => s.LastName == "TestStudent");
        Assert.Equal("First", retrieved.FirstMidName);
    }

    [Fact]
    public void CanAddAndRetrieveCourse()
    {
        var dept = new Department { Name = "Test", Budget = 1000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 5001, Title = "TestCourse", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var retrieved = _context.Courses.Single(c => c.CourseID == 5001);
        Assert.Equal("TestCourse", retrieved.Title);
    }

    [Fact]
    public void CanAddAndRetrieveInstructor()
    {
        var instructor = new Instructor
        {
            LastName = "TestInstructor",
            FirstMidName = "Prof",
            HireDate = new DateTime(2020, 1, 1)
        };

        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var retrieved = _context.Instructors.Single(i => i.LastName == "TestInstructor");
        Assert.Equal("Prof", retrieved.FirstMidName);
    }

    [Fact]
    public void CanAddAndRetrieveDepartment()
    {
        var department = new Department
        {
            Name = "TestDept",
            Budget = 50000,
            StartDate = new DateTime(2022, 1, 1)
        };

        _context.Departments.Add(department);
        _context.SaveChanges();

        var retrieved = _context.Departments.Single(d => d.Name == "TestDept");
        Assert.Equal(50000, retrieved.Budget);
    }

    [Fact]
    public void CanAddEnrollment_WithStudentAndCourse()
    {
        var student = new Student { LastName = "S", FirstMidName = "F", EnrollmentDate = DateTime.Now };
        _context.Students.Add(student);

        var dept = new Department { Name = "D", Budget = 1000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 6001, Title = "C", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var enrollment = new Enrollment { StudentID = student.ID, CourseID = 6001, Grade = Grade.A };
        _context.Enrollments.Add(enrollment);
        _context.SaveChanges();

        var retrieved = _context.Enrollments.Include(e => e.Student).Include(e => e.Course)
            .Single(e => e.StudentID == student.ID && e.CourseID == 6001);
        Assert.Equal(Grade.A, retrieved.Grade);
        Assert.Equal("S", retrieved.Student.LastName);
    }

    [Fact]
    public void CourseAssignment_HasCompositeKey()
    {
        var instructor = new Instructor { LastName = "I", FirstMidName = "F", HireDate = DateTime.Now };
        _context.Instructors.Add(instructor);

        var dept = new Department { Name = "D2", Budget = 1000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 7001, Title = "C2", Credits = 3, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var assignment = new CourseAssignment { InstructorID = instructor.ID, CourseID = 7001 };
        _context.CourseAssignments.Add(assignment);
        _context.SaveChanges();

        var retrieved = _context.CourseAssignments.Find(7001, instructor.ID);
        Assert.NotNull(retrieved);
    }

    [Fact]
    public void OfficeAssignment_OneToOneWithInstructor()
    {
        var instructor = new Instructor { LastName = "Office", FirstMidName = "Test", HireDate = DateTime.Now };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var office = new OfficeAssignment { InstructorID = instructor.ID, Location = "Room 101" };
        _context.OfficeAssignments.Add(office);
        _context.SaveChanges();

        var retrieved = _context.OfficeAssignments.Find(instructor.ID);
        Assert.Equal("Room 101", retrieved.Location);
    }

    [Fact]
    public void Student_InheritsFromPerson()
    {
        var student = new Student { LastName = "Doe", FirstMidName = "Jane", EnrollmentDate = DateTime.Now };
        _context.Students.Add(student);
        _context.SaveChanges();

        var person = _context.People.Find(student.ID);
        Assert.NotNull(person);
        Assert.Equal("Doe", person.LastName);
    }

    [Fact]
    public void Instructor_InheritsFromPerson()
    {
        var instructor = new Instructor { LastName = "Prof", FirstMidName = "Test", HireDate = DateTime.Now };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var person = _context.People.Find(instructor.ID);
        Assert.NotNull(person);
        Assert.Equal("Prof", person.LastName);
    }

    [Fact]
    public void Person_FullName_ReturnsConcatenation()
    {
        var student = new Student { LastName = "Smith", FirstMidName = "John", EnrollmentDate = DateTime.Now };
        Assert.Equal("Smith, John", student.FullName);
    }

    [Fact]
    public void Notification_CanBeStoredAndRetrieved()
    {
        var notification = new Notification
        {
            EntityType = "Student",
            EntityId = "1",
            Operation = "CREATE",
            Message = "Test message",
            CreatedAt = DateTime.Now,
            CreatedBy = "System",
            IsRead = false
        };
        _context.Notifications.Add(notification);
        _context.SaveChanges();

        var retrieved = _context.Notifications.Single();
        Assert.Equal("Student", retrieved.EntityType);
        Assert.Equal("Test message", retrieved.Message);
    }

    [Fact]
    public void Department_CanHaveNullAdministrator()
    {
        var dept = new Department
        {
            Name = "NoAdmin",
            Budget = 10000,
            StartDate = DateTime.Now,
            InstructorID = null
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var retrieved = _context.Departments.Single(d => d.Name == "NoAdmin");
        Assert.Null(retrieved.InstructorID);
    }

    [Fact]
    public void Course_DepartmentRelationship()
    {
        var dept = new Department { Name = "Physics", Budget = 80000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course { CourseID = 8001, Title = "Quantum", Credits = 4, DepartmentID = dept.DepartmentID };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var retrieved = _context.Courses.Include(c => c.Department).Single(c => c.CourseID == 8001);
        Assert.Equal("Physics", retrieved.Department.Name);
    }

    public void Dispose()
    {
        _context.Dispose();
    }
}

